Set(gbl_UI_Book_Modal_Step, "1");
Set(varSelectedRoom, Blank());
Set(varSelectedDate, Today());
Set(varStartTime, Blank());
Set(varEndTime, Blank());
//Set(varTitle, Blank());
//Set(varNotes, Blank());
Set(varConflict, false);
Set(varBookingError, false);
Set(varSubmitting, false);
//Set(varConflictingBooking, Blank());
//Set(varNextFreeSlot, Blank());

ClearCollect(
    varAlternativeRooms,
    Filter(colRooms, true = false)
);

With(
    {
        _now: Now(),
        _todayStart: DateAdd(Today(), 8 * 60, TimeUnit.Minutes)
    },
    With(
        {
            _next: DateAdd(
                _now,
                Mod(
                    15 - Mod(
                        DateDiff(_todayStart, _now, TimeUnit.Minutes),
                        15
                    ),
                    15
                ),
                TimeUnit.Minutes
            )
        },
        With(
            {
                _start: If(
                    _next < _todayStart,
                    _todayStart,
                    _next
                )
            },
            If(
                _start <= DateAdd(_todayStart, 540, TimeUnit.Minutes),
                Set(varStartTime, _start);
                Set(varEndTime, DateAdd(_start, 60, TimeUnit.Minutes))
            )
        )
    )
);

Set(gbl_UI_Book_Modal, true);

AddColumns(
    colRooms,
    RoomStatus,
    With(
        {
            _current: LookUp(colTodayBookings, RoomID.Value = ThisRecord.RoomID.Value && StartDateTime <= Now() && EndDateTime > Now()),
            _next: First(Sort(Filter(colTodayBookings, RoomID.Value = ThisRecord.RoomID.Value && StartDateTime > Now()), StartDateTime, SortOrder.Ascending))
        },
        {
            State: If(!IsBlank(_current), "Busy", IsBlank(_next), "FreeAllDay", DateDiff(Now(), _next.StartDateTime, TimeUnit.Minutes) <= 60, "FreeWarning", "Free"),
            Minutes: DateDiff(Now(), _next.StartDateTime, TimeUnit.Minutes)
        }
    )
)

