Rules.InvariantScript:
Set(varSubmitting, true);
Clear(colFailedBookings);

/* Loop through all occurrences */
ForAll(
    Sequence(
        If(
            tglRecurring.Checked,
            Value(drpWeeks.Selected.Value),
            1
        )
    ),
    With(
        {
            vStart: DateAdd(varStartTime, (Value - 1) * 7, TimeUnit.Days),
            vEnd: DateAdd(varEndTime, (Value - 1) * 7, TimeUnit.Days)
        },
        If(
            !IsBlank(
                LookUp(
                    Book_Bookings,
                    RoomID.Value = varSelectedRoom.RoomID &&
                    StartDateTime < vEnd &&
                    EndDateTime > vStart
                )
            ),

            /* Save failed date */
            Collect(
                colFailedBookings,
                {
                    BookingDate: Text(vStart, "dd mmm yyyy")
                }
            ),

            /* Create booking */
            Patch(
                Book_Bookings,
                Defaults(Book_Bookings),
                {
                    Title: varTitle,
                    RoomID: {
                        Id: Value(varSelectedRoom.ID),
                        Value: varSelectedRoom.RoomID
                    },
                    StartDateTime: vStart,
                    EndDateTime: vEnd,
                    BookedBy: {
                        '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                        Claims: "i:0#.f|membership|" & Lower(User().Email),
                        DisplayName: User().FullName,
                        Email: User().Email,
                        Department: "",
                        JobTitle: "",
                        Picture: ""
                    }
                }
            )
        )
    )
);

/* Tell user what happened */
If(
    CountRows(colFailedBookings) > 0,
    Notify(
        "Some bookings could not be created: " &
        Concat(colFailedBookings, BookingDate, ", "),
        NotificationType.Warning,
        10000
    ),
    Notify(
        "Booking(s) created successfully",
        NotificationType.Success
    );
    Navigate(
        Home,
        ScreenTransition.Fade
    );
    Set(gbl_UI_Book_Modal, false)
);

Set(varSubmitting, false);

ControlPropertyState.AutoRuleBindingString:
UpdateContext({varSubmitting: true, varConflict: false, varBookingError: false});
If(!IsEmpty(Filter(RoomBookings, RoomID.Value = varSelectedRoom.RoomID, StartDateTime < varEndTime, EndDateTime > varStartTime)),
    UpdateContext({varConflict: true, varSubmitting: false}),
        If(IsError(Patch(RoomBookings, 
        Defaults(RoomBookings), 
        {
            Title: varTitle, 
            RoomID: {Id: Value(varSelectedRoom.ID), Value: varSelectedRoom.RoomID}, 
            StartDateTime: varStartTime, 
            EndDateTime: varEndTime, 
            BookedBy: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(User().Email),
                DisplayName: User().FullName,
                Email: User().Email,
                Department: "",
                JobTitle: "",
                Picture: ""
            }
        }
    )
), 
    UpdateContext(
        {
            varSubmitting: false, 
            varBookingError: true
        }
    ), 
    UpdateContext(
        {
            varSubmitting: false
        }
    ); Notify("Room booked successfully", NotificationType.Success); Navigate(Home, ScreenTransition.Fade)))

